from sympy import isprime
from math import gcd



DIGITS = [6, 7]

def search(n, max_len=260):
    states = [(0, 0, 1)]  
    # (p_mod, q_mod, modulus)

    for k in range(1, max_len + 1):
        new_states = []
        mod = 10 ** k

        for p_prev, q_prev, _ in states:
            for dp in DIGITS:
                for dq in DIGITS:
                    p_new = p_prev + dp * 10 ** (k - 1)
                    q_new = q_prev + dq * 10 ** (k - 1)

                    if (p_new * q_new - n) % mod == 0:
                        new_states.append((p_new, q_new, mod))

        print(f"[+] k={k}, states={len(new_states)}")

        states = new_states
        if not states:
            break

        # 尝试直接整除
        for p_candidate, _, _ in states:
            g = gcd(n, p_candidate)
            if g != 1 and g != n:
                return g, n // g

    return None, None

p, q = search(n)

print("p =", p)
print("q =", q)

assert p * q == n
assert isprime(p)
assert isprime(q)


